  assert.ok(correctionClientInputOwned(input,fixture),'CORRECTIONS_ACK_CLIENT_INPUT_STOP');assert.ok(actor.roles?.some(role=>['ADMIN','DIRECTOR','MANAGER'].includes(role)),'CORRECTIONS_ACK_CLIENT_ROLE_STOP');assert.equal(journal.extraClientWrites.length,0,'CORRECTIONS_ONE_CLIENT_STOP');assert.ok(finalFileId(result.id)&&![fixture.ids.clientA,fixture.ids.clientB].includes(result.id),'CORRECTIONS_CLIENT_ID_STOP');
